  (* [comment removed for export] *)
  Theorem as_exit_flush : forall regs mem msF mo (sp code we re ro : word) (tid can wp : Z) (pending : list byte),
    axH true mem sp tid can we re ro ->
    rdn RSEGS mem (Z_to_bv 64 0x124008) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 wp)) ->     (* [comment removed for export] *)
    cells_ok mem ax_flush_cells ->                                                          (* [comment removed for export] *)
    (0x681f01 <= wp <= 0x682300)%Z -> (wp - 0x681f00 = Z.of_nat (length pending))%Z ->
    rdn RSEGS mem (Z_to_bv 64 0x681f00) (length pending) = Some pending ->
    getr regs 2 = sp -> getr regs 4 = Z_to_bv 64 0x6617f0 -> getr regs 10 = code ->
    fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> restrict L S msF = mkst regs (Z_to_bv 64 AEXIT) mem (seg_rom RSEGS) ->
